	for (int i = 0; i < GTAO_HORIZON_STEPS; ++i, ray_pos += ray_step) {
        ivec2 shaderlodAoOffset = ivec2(clamp(ray_pos,0.0,1.0) * view_res * taau_render_scale - 0.5);
