    // equal to Albedo * +0, including signed zero. Retain the native mix operation.
    if (shaderlod_optimization_enabled(shaderlodOptZeroEmissionArithmetic) &&
        floatBitsToUint(Emission) == 0u && Emissive_Curve >= 0.1 && Emissive_Curve <= 3.0 &&
        Emissive_Brightness >= 1.0 && Emissive_Brightness <= 100.0 &&
        abs(exposure) <= 8.0 && all(bvec3(Albedo.x == 0.0 || abs(Albedo.x) >= 4e-38,
                  Albedo.y == 0.0 || abs(Albedo.y) >= 4e-38,
                  Albedo.z == 0.0 || abs(Albedo.z) >= 4e-38)) &&
        all(lessThanEqual(abs(Albedo), vec3(1e6))) &&
        all(lessThanEqual(abs(Lighting), vec3(1e20)))) {
        Lighting = mix(Lighting, Albedo, 0.0);
        return;
    }
    #endif
	float autoBrightnessAdjust = mix(5.0, 100.0, clamp(exp(-10.0*exposure),0.0,1.0));
	if( Emission < 254.5/255.0) Lighting = mix(Lighting, Albedo * Emissive_Brightness * autoBrightnessAdjust, pow(Emission, Emissive_Curve)); // old method.... idk why
	// if( Emission < 254.5/255.0 ) Lighting += (Albedo * Emissive_Brightness) * pow(Emission, Emissive_Curve);
}

