	/////////////////////////////////////////////////////////////////////////////////

		#if defined OVERWORLD_SHADER
			float skylight = 1.0;
		
			#if indirect_effect == 0 || indirect_effect == 1 || indirect_effect == 2
				float SkylightDir = (slopednormal / dot(abs(slopednormal),vec3(1.0))).y*1.5;
