float encodeVec2(vec2 a){
    const vec2 constant1 = vec2( 1., 256.) / 65535.;
    vec2 temp = floor( a * 255. );
	return temp.x*constant1.x+temp.y*constant1.y;
}
float encodeVec2(float x,float y){
    return encodeVec2(vec2(x,y));
}


float invLinZ (float lindepth){
	return -((2.0*near/lindepth)-far-near)/(far-near);
}
float ld(float dist) {
    return (2.0 * near) / (far + near - dist * (far - near));
}

vec3 rayTrace(vec3 dir, vec3 position,float dither, float fresnel, bool inwater, inout float reflectLength){

    float quality = mix(15,SSR_STEPS,fresnel);
	#if SHADERLOD_EFFECT_ADAPTER == 1 && defined OVERWORLD_SHADER && !defined DISTANT_HORIZONS && !defined VOXY
	int shaderlodTraceIterations = int(quality) + 1;
	if (!inwater && quality >= 1.0 && quality <= 65535.0 && all(lessThan(abs(position),vec3(1e6)))) {
		int shaderlodTraceSelected = shaderlod_bliss_distance_budget(shaderlodOptReflectionTraceBudget, length(position), shaderlodTraceIterations, 8);
		// Native loop includes its terminal step; retain that total interval.
		quality *= float(shaderlodTraceSelected) / float(shaderlodTraceIterations);
		shaderlodTraceIterations = shaderlodTraceSelected;
	}
	#endif
	
    // quality = SSR_STEPS;

    vec3 clipPosition = toClipSpace3(position);
	float rayLength = ((position.z + dir.z * far*sqrt(3.)) > -near) ?
       (-near -position.z) / dir.z : far*sqrt(3.);
    vec3 direction = normalize(toClipSpace3(position+dir*rayLength)-clipPosition);  //convert to clip space
    direction.xy = normalize(direction.xy);

    //get at which length the ray intersects with the edge of the screen
    vec3 maxLengths = (step(0.,direction)-clipPosition) / direction;
    float mult = min(min(maxLengths.x,maxLengths.y),maxLengths.z);


    vec3 stepv = direction * mult / quality * vec3(RENDER_SCALE,1.0);


	vec3 spos = clipPosition*vec3(RENDER_SCALE,1.0) + stepv*dither;
	float minZ = clipPosition.z;
	float maxZ = spos.z+stepv.z*0.5;
	
	spos.xy += offsets[framemod8]*texelSize*0.5/RENDER_SCALE;

	float dist = 1.0 + clamp(position.z*position.z/50.0,0,2); // shrink sample size as distance increases
	#if SHADERLOD_EFFECT_ADAPTER == 1 && defined OVERWORLD_SHADER && !defined DISTANT_HORIZONS && !defined VOXY
	for (int i = 0; i < shaderlodTraceIterations; i++) {
	#else
    for (int i = 0; i <= int(quality); i++) {
	#endif

		// decode depth buffer
		// float sp = sqrt(texelFetch2D(colortex4,ivec2(spos.xy/texelSize/4),0).w/65000.0);

		float sp = sqrt(texelFetch2D(colortex4,ivec2(spos.xy/texelSize/4.0),0).a/65000.0);
		sp = invLinZ(sp);

        if(sp <= max(maxZ,minZ) && sp >= min(maxZ,minZ)) return vec3(spos.xy/RENDER_SCALE,sp);




        spos += stepv;
		//small bias
#if SHADERLOD_EFFECT_ADAPTER == 1 && defined OVERWORLD_SHADER && !defined DISTANT_HORIZONS && !defined VOXY && MC_VERSION == 12101
        // Native hit tests/depth fetches have already run for this visit.
        // The final failed visit has no following depth-range consumer.
        if (!shaderlod_optimization_enabled(shaderlodOptSsrProjectionArithmetic) ||
            i + 1 < shaderlodTraceIterations) {
		if(inwater) {
			minZ = maxZ-0.00035/ld(spos.z);
		}else{
			minZ = maxZ-0.0001/max(ld(spos.z), (0.0 + position.z*position.z*0.001));
		}
		maxZ += stepv.z;
        }
#else
		if(inwater) {
			minZ = maxZ-0.00035/ld(spos.z);
		}else{
			minZ = maxZ-0.0001/max(ld(spos.z), (0.0 + position.z*position.z*0.001));
		}
		maxZ += stepv.z;
#endif

		
		reflectLength += 1.0 / quality; // for shit
    }

    return vec3(1.1);
}

float GGX(vec3 n, vec3 v, vec3 l, float r, float f0) {
  r = max(pow(r,2.5), 0.0001);

  vec3 h = l + v;
  float hn = inversesqrt(dot(h, h));

  float dotLH = clamp(dot(h,l)*hn,0.,1.);
  float dotNH = clamp(dot(h,n)*hn,0.,1.) ;
  float dotNL = clamp(dot(n,l),0.,1.);
  float dotNHsq = dotNH*dotNH;

  float denom = dotNHsq * r - dotNHsq + 1.;
  float D = r / (3.141592653589793 * denom * denom);

  float F = f0 + (1. - f0) * exp2((-5.55473*dotLH-6.98316)*dotLH);
  float k2 = .25 * r;

  return dotNL * D * F / (dotLH*dotLH*(1.0-k2)+k2);
}



